desired_state = {"api": {"replicas": 3, "image": "api:2.4"}}
live_state = {"api": {"replicas": 1, "image": "api:2.4"}}

def reconcile(desired, live):
    changes = []
    for name, spec in desired.items():
        current = live.get(name, {})
        for key, value in spec.items():
            if current.get(key) != value:
                changes.append(f"{name}.{key}: {current.get(key)} -> {value}")
                current[key] = value
        live[name] = current
    return changes

diffs = reconcile(desired_state, live_state)
for d in diffs:
    print("aplicado:", d)
print("estado final:", live_state)
